const tg = window.Telegram?.WebApp;
const initData = tg?.initData || '';
const previewMode = !initData && new URLSearchParams(location.search).get('preview') === '1';
let bootstrapData=null, currentProfile=null, referralLink='', activeChallenge='';
let memoryPicks=[], memoryState=null, profileInventory=[], clanCache=[], breakoutState=null, breakoutInputHandler=null, wheelBusy=false, wheelRotation=0, toastTimer, liveArenaPoll=null, liveArenaMatchId=null, arcadeState=null, globalChatRefreshTimer=null;
if(tg){tg.ready();tg.expand();try{tg.setHeaderColor('#090b18');tg.setBackgroundColor('#090b18');}catch(e){}}

async function api(path,method='GET',body=null){
  const headers={'X-Telegram-Init-Data':initData}; if(body!==null)headers['Content-Type']='application/json';
  const response=await fetch(path,{method,headers,body:body!==null?JSON.stringify(body):undefined});
  const data=await response.json().catch(()=>({detail:'پاسخ سرور قابل خواندن نیست.'}));
  if(!response.ok)throw new Error(data.detail||'ارتباط با سرور برقرار نشد.'); return data;
}
async function apiUpload(path,form){
  const response=await fetch(path,{method:'POST',headers:{'X-Telegram-Init-Data':initData},body:form});
  const data=await response.json().catch(()=>({detail:'پاسخ سرور قابل خواندن نیست.'}));
  if(!response.ok)throw new Error(data.detail||'آپلود ناموفق بود.');return data;
}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);try{tg?.HapticFeedback?.notificationOccurred('success')}catch(e){}}
function initials(name='GA'){return String(name).trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('')||'GA'}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function fmt(n){return Number(n||0).toLocaleString('fa-IR')}
function setAvatar(el,p){
  if(!el)return;
  el.innerHTML='';el.classList.add('avatar-frame-host');
  const photo=document.createElement('div');photo.className='avatar-portrait';
  if(p.photo_url){const img=document.createElement('img');img.src=p.photo_url;img.alt='عکس پروفایل';img.referrerPolicy='no-referrer';img.onerror=()=>{photo.textContent=initials(p.name)};photo.appendChild(img)}else photo.textContent=initials(p.name);
  el.appendChild(photo);
  const frame=profileInventory.find(x=>x.product_id===p.equipped_frame_id&&x.category==='frame');
  if(frame?.image_url){const ring=document.createElement('img');ring.className='frame-ring';ring.src=frame.image_url;ring.alt='قاب پروفایل';ring.referrerPolicy='no-referrer';el.appendChild(ring)}
  el.classList.toggle('has-frame',!!frame);
}
function vipMark(p){const names={vip:'VIP',vip_plus:'VIP+',elite:'ELITE',legend:'LEGEND'};return names[p?.vip_tier]&&p.vip_tier!=='none'?`<span class="vip-pill vip-${p.vip_tier}">${names[p.vip_tier]}</span>`:''}
function identityMarks(p){if(p.is_owner)return '<span class=\"owner-crest\" title=\"مالک اصلی GAME ARENA\"><span class=\"owner-crown\">♛</span><span class=\"owner-crest-text\"><b>مالک</b><small>FOUNDER</small></span></span>';return p.is_verified?'<span class=\"verified-mark\" title=\"حساب تأییدشده\" aria-label=\"حساب تأییدشده\">✓</span>':''}
function equippedProduct(id){return profileInventory.find(x=>x.product_id===id)}
function renderCharacterStage(el,imageUrl,label,{owner=false,publicView=false}={}){
  if(!el)return;
  el.classList.toggle('hidden',!imageUrl);
  if(!imageUrl){el.innerHTML='';return}
  el.classList.toggle('owner-character-stage',!!owner);
  el.classList.toggle('public-character-stage',!!publicView);
  const is3D=/\.glb(?:[?#]|$)/i.test(imageUrl);
  const ownerCamera=owner?'camera-target="0m 2.85m 0m" camera-orbit="0deg 76deg 9.2m" min-camera-orbit="auto 42deg 7.0m" max-camera-orbit="auto 112deg 13m"':'camera-target="0m 2.25m 0m" camera-orbit="0deg 78deg 6.1m" min-camera-orbit="auto 35deg 4.2m" max-camera-orbit="auto 105deg 8m"';
  const viewer=is3D?`<model-viewer class="character-model-viewer" src="${escapeHtml(imageUrl)}" alt="کاراکتر سه‌بعدی قابل چرخش" camera-controls auto-rotate rotation-per-second="10deg" interaction-prompt="none" shadow-intensity="1.25" exposure="1.05" ${ownerCamera} environment-image="neutral" loading="eager"></model-viewer>`:`<img src="${escapeHtml(imageUrl)}" alt="کاراکتر نمایشی" loading="eager">`;
  el.innerHTML=`<div class="character-stage-label"><span>${is3D?'INTERACTIVE 3D MODEL':(owner?'OWNER CHARACTER':'PLAYER MODEL')}</span><b>${escapeHtml(label)}</b></div><div class="character-render">${viewer}</div><div class="model-hint">برای چرخاندن، مدل را با انگشت بکش؛ برای بزرگ‌نمایی دو انگشت را باز کن.</div>`;
  const model=el.querySelector('.character-render model-viewer');
  model?.addEventListener('error',()=>{const render=el.querySelector('.character-render');if(render)render.innerHTML='<div class="character-image-fallback">مدل سه‌بعدی بارگذاری نشد. مسیر فایل GLB را بررسی کن.</div>'},{once:true});
  const img=el.querySelector('.character-render img');
  img?.addEventListener('error',()=>{const render=el.querySelector('.character-render');if(render)render.innerHTML='<div class="character-image-fallback">تصویر کاراکتر بارگذاری نشد؛ مسیر فایل یا فضای ذخیره‌سازی را بررسی کن.</div>'},{once:true});
}
function applyEquippedCosmetics(){
  if(!currentProfile)return;
  setAvatar(document.getElementById('avatar'),currentProfile);setAvatar(document.getElementById('profileAvatar'),currentProfile);
  const character=equippedProduct(currentProfile.equipped_character_id||currentProfile.equipped_avatar_id);
  const ownerCharacter=currentProfile.owner_character_url;
  const customCharacter=currentProfile.custom_character_url;
  const characterUrl=customCharacter||ownerCharacter||character?.image_url||null;
  const characterLabel=currentProfile.is_owner?(customCharacter?'کاراکتر شخصی مالک':'فرمانروای GAME ARENA'):(customCharacter?'کاراکتر شخصی':(character?.name||''));
  renderCharacterStage(document.getElementById('profileCharacterStage'),characterUrl,characterLabel,{owner:!!ownerCharacter});
  const badge=equippedProduct(currentProfile.equipped_badge_id);
  const gift=equippedProduct(currentProfile.equipped_gift_id);
  const showcase=equippedProduct(currentProfile.equipped_showcase_id);
  const badgeEl=document.getElementById('profileEquippedBadge');
  if(badgeEl)badgeEl.innerHTML=badge?`<span class="equipped-chip">${badge.image_url?`<img src="${escapeHtml(badge.image_url)}" alt="">`:''}${escapeHtml(badge.name)}</span>`:'';
  const giftEl=document.getElementById('profileGiftShowcase');
  if(giftEl){const gifts=profileInventory.filter(x=>x.category==='gift');giftEl.innerHTML=gifts.length?`<div class="gift-collection-title">🎁 هدایای دریافتی</div><div class="gift-collection-items">${gifts.map(x=>`<div class="gift-collectible" title="${escapeHtml(x.name)}">${x.image_url?`<img src="${escapeHtml(x.image_url)}" alt="${escapeHtml(x.name)}">`:'🎁'}<small>${escapeHtml(x.name)}</small></div>`).join('')}</div>`:''}
  const showEl=document.getElementById('profileShowcase');
  if(showEl)showEl.innerHTML=showcase?`<div class="equipped-chip">${showcase.image_url?`<img src="${escapeHtml(showcase.image_url)}" alt="">`:''}${escapeHtml(showcase.name)}</div>`:'';
  const cosmeticsEl=document.getElementById('profileCosmetics');
  if(cosmeticsEl){
    const labels={character:'کاراکتر سه‌بعدی',frame:'قاب دور عکس',badge:'نشان پروفایل',gift:'هدیه مالک',showcase:'آیتم نمایشی',pack:'بسته جایزه'};
    cosmeticsEl.innerHTML=profileInventory.length?profileInventory.map(x=>{const action=x.is_pack?`<button onclick="openPack(${x.product_id})">بازکردن بسته</button>`:(['character','frame','badge','gift','showcase'].includes(x.equip_slot)?`<button onclick="equipProduct(${x.product_id})">${x.equipped?'برداشتن':'انتخاب'}</button>`:'');return `<div class="list-card inventory-row"><div>${x.image_url?`<img class="mini-cosmetic" src="${escapeHtml(x.image_url)}" alt="">`:''}<div><b>${labels[x.equip_slot]||'آیتم'} · ${escapeHtml(x.name)}</b><small>${x.is_pack?'بسته جایزه · ':''}${x.equipped?'اکنون فعال است':'در کوله‌پشتی'} · تعداد ${fmt(x.quantity)}</small></div></div>${action}</div>`}).join(''):'<p class="helper">هنوز آیتمی در کوله‌پشتی نیست. کاراکتر و قاب را از فروشگاه تهیه کن؛ هدایا و بسته‌ها را مالک اعطا می‌کند.</p>';
  }
}
function renderProfile(p){
  currentProfile=p;
  document.getElementById('helloName').innerHTML=`${escapeHtml(p.name)} ${identityMarks(p)} ${vipMark(p)}`;
  setAvatar(document.getElementById('avatar'),p);setAvatar(document.getElementById('profileAvatar'),p);
  document.getElementById('xp').textContent=fmt(p.xp);document.getElementById('league').textContent=p.league;
  document.getElementById('wins').textContent=fmt(p.wins);document.getElementById('games').textContent=fmt(p.games);
  document.getElementById('streak').textContent=fmt(p.streak)+' 🔥';document.getElementById('coins').textContent=fmt(p.coins);document.getElementById('shopCoins').textContent=fmt(p.coins);
  document.getElementById('level').textContent=fmt(p.level);
  const thresholds=[0,250,1000,2000,3000,5000,8000], floor=[...thresholds].reverse().find(x=>p.xp>=x)||0;
  const next=p.next_league||{left:0,name:'حداکثر لیگ',at:p.xp};
  const pct=next.left===0?100:Math.max(3,Math.min(100,((p.xp-floor)/(next.at-floor))*100));
  document.getElementById('xpBar').style.width=pct+'%';document.getElementById('nextLeague').textContent=next.left===0?'بالاترین لیگ':'تا '+next.name;
  document.getElementById('xpLeft').textContent=next.left===0?'MAX':fmt(next.left)+' XP';
  document.getElementById('profileName').innerHTML=`${escapeHtml(p.name)} ${identityMarks(p)} ${vipMark(p)}`;
  const vipEl=document.getElementById('profileVipBadge');if(vipEl)vipEl.innerHTML=vipMark(p)?`<span class="equipped-chip">⭐ عضویت ${vipMark(p)}</span>`:'';document.getElementById('profileLeague').textContent=p.league;
  document.getElementById('profileIdentity').textContent=`ID: ${p.id} · ${p.username?'@'+p.username:'بدون نام کاربری'}`;
  document.getElementById('pGames').textContent=fmt(p.games);document.getElementById('pWins').textContent=fmt(p.wins);document.getElementById('pLosses').textContent=fmt(p.losses);
  document.getElementById('pRate').textContent=p.win_rate+'%';document.getElementById('pXP').textContent=fmt(p.xp);
  applyEquippedCosmetics();
}
function renderMissions(items){document.getElementById('missions').innerHTML=items.map(m=>`<div class="mission"><div class="mission-top"><span>${escapeHtml(m.title)}</span><span>${m.progress}/${m.target} · +${m.reward} XP</span></div><div class="mission-bar"><i style="width:${Math.min(100,m.progress/m.target*100)}%"></i></div><div class="mission-actions"><button class="mission-claim" ${m.claimed||m.progress<m.target?'disabled':''} onclick="claimMission(${m.id})">${m.claimed?'دریافت شد':m.progress>=m.target?'دریافت جایزه':'در حال انجام'}</button></div></div>`).join('')}
async function claimMission(id){try{const d=await api('/api/missions/claim','POST',{mission_id:id});renderProfile(d.profile);const fresh=await api('/api/bootstrap');renderMissions(fresh.missions);toast('🎯 جایزه مأموریت: +'+d.reward+' XP')}catch(e){toast(e.message)}}
async function boot(){
  if(!initData && previewMode){
    const mock={id:7347642182,name:'قهرمان دمو',username:'arena_player',photo_url:null,is_owner:true,owner_character_url:'/static/owner/royal-throne.glb?v=3.0.0',is_verified:true,xp:680,games:42,wins:29,losses:13,streak:4,coins:860,level:7,league:'🥇 Gold',next_league:{name:'💎 Diamond',at:1200,left:520},win_rate:69};
    renderProfile(mock);renderMissions([{id:0,title:'۳ بازی امروز انجام بده',progress:2,target:3,reward:20,claimed:false},{id:1,title:'یک مسابقه را ببر',progress:1,target:1,reward:15,claimed:false},{id:2,title:'۵ بازی در یک روز',progress:2,target:5,reward:35,claimed:false}]);
    document.getElementById('previewNotice').classList.remove('hidden');document.getElementById('loading').classList.add('hidden');document.getElementById('app').classList.remove('hidden');
    document.querySelectorAll('#app button').forEach(b=>{if(!b.closest('.bottom-nav')){b.disabled=true;b.title='در پیش‌نمایش، عملیات واقعی غیرفعال است'}});return;
  }
  if(!initData){document.getElementById('loading').innerHTML='<div class="logo-orb">GA</div><b>GAME ARENA 3.0</b><span>برای امنیت، این مینی‌اپ را از داخل ربات تلگرام باز کن. برای مشاهده ظاهر صفحه در مرورگر از ?preview=1 استفاده کن.</span>';return}
  try{
    const access=await api('/api/access');
    if(access.required&&!access.joined){showJoinGate(access);return;}
    document.getElementById('joinGate').classList.add('hidden');
    bootstrapData=await api('/api/bootstrap');referralLink=bootstrapData.referral_link||'';renderProfile(bootstrapData.profile);renderMissions(bootstrapData.missions);renderEvents(bootstrapData.active_events||[]);if(bootstrapData.season)document.getElementById('seasonBadge').textContent=bootstrapData.season.name;
    if(bootstrapData.is_admin){document.getElementById('adminBox').classList.remove('hidden');loadAdmin()}
    applyGameAvailability(bootstrapData.game_status||{});
    if(bootstrapData.daily_claimed){const b=document.getElementById('dailyBtn');b.textContent='دریافت شد';b.disabled=true}
    document.getElementById('loading').classList.add('hidden');document.getElementById('app').classList.remove('hidden');
    loadLeaderboard('all');loadWheelStatus();loadProfileExtras();loadSeasonHub();loadNotifications();loadArenaFeed();
  }catch(e){document.getElementById('loading').innerHTML=`<div class="logo-orb">GA</div><b>ورود ناموفق</b><span>${escapeHtml(e.message)}</span>`}
}
function applyGameAvailability(status){const map={math:'startMath()',ttt:'startTTT()',penalty:"openSports('penalty')",basketball:"openSports('basketball')",volleyball:"openSports('volleyball')",guess:'startGuess()',memory:'startMemory()', 'neon-breakout':'startNeonBreakout()','space-shooter':"startArcade('space-shooter')",'neon-drift':"startArcade('neon-drift')"};for(const [key,handler] of Object.entries(map)){if(status[key]===false){document.querySelectorAll(`button[onclick=\"${handler}\"]`).forEach(el=>{el.disabled=true;el.style.opacity='.35';el.title='این بازی موقتاً غیرفعال است'})}}}
function showJoinGate(access){
  document.getElementById('loading').classList.add('hidden');
  document.getElementById('app').classList.add('hidden');
  const gate=document.getElementById('joinGate');
  document.getElementById('joinGateTitle').textContent=access.title||'کانال رسمی GAME ARENA';
  const link=document.getElementById('joinLink');
  link.href=access.invite_url||'https://t.me/';
  link.classList.toggle('disabled-link',!access.invite_url);
  document.getElementById('joinGateMessage').textContent=access.message||'برای باز شدن بازی‌ها، ابتدا عضو کانال شو و بعد عضویتت را بررسی کن.';
  gate.classList.remove('hidden');
}
async function checkJoinStatus(){
  const btn=document.getElementById('joinCheckBtn');btn.disabled=true;btn.textContent='در حال بررسی...';
  try{const d=await api('/api/access');if(d.required&&!d.joined){showJoinGate(d);toast('هنوز عضویتت در کانال تأیید نشده است.');}
    else{document.getElementById('joinGate').classList.add('hidden');toast('عضویت تأیید شد؛ خوش آمدی!');boot();}}
  catch(e){toast(e.message)}finally{btn.disabled=false;btn.textContent='بررسی عضویت'}
}
function switchTab(id,btn){document.querySelectorAll('.tab-panel').forEach(x=>x.classList.add('hidden'));document.getElementById(id).classList.remove('hidden');document.querySelectorAll('.bottom-nav button').forEach(x=>x.classList.remove('active'));btn?.classList.add('active');if(previewMode){renderPreviewTab(id);return}if(id==='competitionTab')loadCompetition();if(id==='shopTab')loadShop();if(id==='profileTab')loadProfileExtras()}
function renderPreviewTab(id){if(id==='competitionTab'){document.getElementById('myRank').textContent='#۱۲';document.getElementById('leaderboard').innerHTML=['نئون‌باز','قهرمان دمو','ستاره آبی'].map((n,i)=>`<div class="rank-row"><div class="rank-no">${i+1}</div><div class="rank-name">${n}</div><div class="rank-meta"><b>${[1250,680,540][i]} XP</b><small>${i===0?'💎 Diamond':'🥇 Gold'}</small></div></div>`).join('');document.getElementById('myClan').textContent='👥 کلن سایبر · ۱۲ عضو';document.getElementById('clanList').innerHTML='<div class="list-card"><b>کلن سایبر</b><span>۱۲ عضو</span></div><div class="list-card"><b>ستاره‌ها</b><span>۸ عضو</span></div>';document.getElementById('friendChallenges').innerHTML='<div class="list-card"><b>⚔️ چالش دوستان</b><small>دعوت پذیرفته‌شده · نبرد ریاضی</small></div>';document.getElementById('tournamentList').innerHTML='<div class="list-card"><b>🏆 جام نئون</b><small>تورنمنت حذفی · ۸/۱۶ نفر · جایزه ۵۰۰ سکه</small></div>';}
if(id==='shopTab'){document.getElementById('shopProducts').innerHTML=['کاراکتر سه‌بعدی نئون','قاب دور عکس','نشان قهرمان'].map((n,i)=>`<div class="product-card"><div class="product-art">${['🧍','🖼️','🏅'][i]}</div><b>${n}</b><small>پیش‌نمایش فروشگاه</small><span class="rarity rare">${i===2?'epic':'rare'}</span><div class="product-buy"><strong>🪙 ${[180,150,100][i]}</strong><button disabled>خرید</button></div></div>`).join('');document.getElementById('inventoryList').innerHTML='<div class="list-card"><b>نمونه قاب دور عکس</b><span>🎒 ×۱</span></div>';}
if(id==='profileTab'){document.getElementById('achievementList').innerHTML='<div class="list-card unlocked"><b>🏅 اولین پیروزی</b><span>✅</span></div><div class="list-card"><b>👑 افسانه میدان</b><span>🔒</span></div>';document.getElementById('matchHistory').innerHTML='<div class="list-card"><b>NEON BREAKOUT · برد</b><strong>+۴۵ XP</strong></div><div class="list-card"><b>نبرد ریاضی · برد</b><strong>+۱۲ XP</strong></div>';}}
function showModal(title,html){stopBreakoutLoop();stopArcade();memoryPicks=[];document.getElementById('modalTitle').textContent=title;document.getElementById('gameArea').innerHTML=html;document.getElementById('modal').classList.remove('hidden')}
function closeModal(){stopBreakoutLoop();stopArcade();document.getElementById('modal').classList.add('hidden');memoryPicks=[]}
async function refreshProfile(){try{const d=await api('/api/bootstrap');bootstrapData=d;renderProfile(d.profile);renderMissions(d.missions);renderEvents(d.active_events||[])}catch(e){}}

// Version 3.0: Space Shooter and Neon Drift Canvas arcade sessions.
function stopArcade(){if(arcadeState?.raf)cancelAnimationFrame(arcadeState.raf);if(arcadeState?.cleanup)arcadeState.cleanup();arcadeState=null}
async function startArcade(game){
  try{const d=await api('/api/games/arcade/start','POST',{game});
    const title=game==='space-shooter'?'🚀 SPACE SHOOTER':'🏎️ NEON DRIFT';
    showModal(title,`<div class="arcade-hud"><span>امتیاز <b id="arcadeScore">۰</b></span><span>زمان <b id="arcadeTime">۰</b></span><span>❤️ <b id="arcadeLives">۳</b></span></div><canvas id="arcadeCanvas" width="360" height="470" class="arcade-canvas"></canvas><div class="arcade-controls"><button onpointerdown="arcadeMove(-1)" onpointerup="arcadeMove(0)" onpointerleave="arcadeMove(0)">◀</button><button onpointerdown="arcadeFire()" onpointerup="arcadeStopFire()" onpointerleave="arcadeStopFire()">${game==='space-shooter'?'شلیک':'بوست'}</button><button onpointerdown="arcadeMove(1)" onpointerup="arcadeMove(0)" onpointerleave="arcadeMove(0)">▶</button></div><p id="arcadeMessage" class="helper">با لمس صفحه یا دکمه‌ها حرکت کن؛ برخوردها جان کم می‌کنند. حداقل ۸ ثانیه برای ثبت نتیجه لازم است.</p>`);
    const canvas=document.getElementById('arcadeCanvas');if(!canvas)return;
    arcadeState={game,challengeId:d.challenge_id,ctx:canvas.getContext('2d'),canvas,score:0,lives:3,x:180,y:game==='space-shooter'?410:390,move:0,fire:false,bullets:[],targets:[],particles:[],last:performance.now(),started:performance.now(),spawn:0,raf:0,dead:false,finishing:false,boost:0};
    for(let i=0;i<5;i++)arcadeState.targets.push({x:35+Math.random()*290,y:-i*100-20,w:game==='space-shooter'?28:26,h:game==='space-shooter'?24:34,speed:2.1+Math.random()*1.2});
    const keydown=e=>{if(['ArrowLeft','ArrowRight',' ','a','d','A','D'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft'||e.key.toLowerCase()==='a')arcadeMove(-1);if(e.key==='ArrowRight'||e.key.toLowerCase()==='d')arcadeMove(1);if(e.key===' ')arcadeFire()}};
    const keyup=e=>{if(['ArrowLeft','ArrowRight','a','d','A','D'].includes(e.key))arcadeMove(0);if(e.key===' ')arcadeStopFire()};
    window.addEventListener('keydown',keydown);window.addEventListener('keyup',keyup);arcadeState.cleanup=()=>{window.removeEventListener('keydown',keydown);window.removeEventListener('keyup',keyup)};
    canvas.addEventListener('pointermove',e=>{if(!arcadeState)return;const r=canvas.getBoundingClientRect();arcadeState.x=Math.max(20,Math.min(340,(e.clientX-r.left)/r.width*360))});
    runArcadeFrame();
  }catch(e){toast(e.message)}
}
function arcadeMove(dir){if(arcadeState)arcadeState.move=dir}
function arcadeFire(){if(arcadeState)arcadeState.fire=true}
function arcadeStopFire(){if(arcadeState)arcadeState.fire=false}
function runArcadeFrame(){const st=arcadeState;if(!st)return;const now=performance.now(),dt=Math.min(.04,(now-st.last)/1000);st.last=now;const t=(now-st.started)/1000,ctx=st.ctx;ctx.clearRect(0,0,360,470);ctx.fillStyle='#070d20';ctx.fillRect(0,0,360,470);
  for(let i=0;i<42;i++){ctx.fillStyle=i%3?'#3b5f93':'#9ae8ff';ctx.globalAlpha=.25+(i%5)*.1;ctx.fillRect((i*83)%360,(i*47+t*24)%470,2,2)}ctx.globalAlpha=1;
  if(!st.dead){st.x=Math.max(18,Math.min(342,st.x+st.move*250*dt));st.spawn-=dt;
    if(st.game==='space-shooter'&&st.fire&&now-(st.lastShot||0)>170){st.bullets.push({x:st.x,y:st.y-15,vy:-390});st.lastShot=now}
    if(st.game==='neon-drift'&&st.fire)st.boost=Math.min(1,st.boost+dt*2);else st.boost=Math.max(0,st.boost-dt*2);
    if(st.spawn<=0){st.targets.push({x:25+Math.random()*310,y:-30,w:st.game==='space-shooter'?27:24,h:st.game==='space-shooter'?24:34,speed:2.2+Math.random()*1.8});st.spawn=st.game==='space-shooter'?.72:.85}
    st.targets.forEach(o=>{o.y+=(o.speed+(st.boost*2))*60*dt});st.bullets.forEach(b=>b.y+=b.vy*dt);st.bullets=st.bullets.filter(b=>b.y>-20);
    if(st.game==='space-shooter'){
      st.targets=st.targets.filter(o=>{const hit=st.bullets.some(b=>Math.abs(b.x-o.x)<o.w/2+3&&Math.abs(b.y-o.y)<o.h/2+4);if(hit){st.bullets=st.bullets.filter(b=>!(Math.abs(b.x-o.x)<o.w/2+3&&Math.abs(b.y-o.y)<o.h/2+4));st.score+=12;return false}if(o.y>490){st.score+=1;return false}if(Math.abs(o.x-st.x)<o.w/2+13&&Math.abs(o.y-st.y)<o.h/2+13){st.lives--;o.y=520;if(st.lives<=0)st.dead=true}return true});
      ctx.fillStyle='#7ce8ff';st.bullets.forEach(b=>{ctx.fillRect(b.x-2,b.y-8,4,14)});
    }else{
      st.targets=st.targets.filter(o=>{if(o.y>490){st.score+=18;return false}if(Math.abs(o.x-st.x)<24&&Math.abs(o.y-st.y)<25){st.lives--;o.y=520;if(st.lives<=0)st.dead=true}return true});
    }
  }
  st.targets.forEach(o=>{ctx.fillStyle=st.game==='space-shooter'?'#ff718f':'#ffb84f';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=14;if(st.game==='space-shooter'){ctx.beginPath();ctx.moveTo(o.x,o.y-o.h/2);ctx.lineTo(o.x+o.w/2,o.y+o.h/2);ctx.lineTo(o.x-o.w/2,o.y+o.h/2);ctx.closePath();ctx.fill()}else{ctx.fillRect(o.x-o.w/2,o.y-o.h/2,o.w,o.h)}ctx.shadowBlur=0});
  ctx.fillStyle=st.game==='space-shooter'?'#72e9ff':'#a58bff';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=20;if(st.game==='space-shooter'){ctx.beginPath();ctx.moveTo(st.x,st.y-18);ctx.lineTo(st.x+15,st.y+14);ctx.lineTo(st.x,st.y+8);ctx.lineTo(st.x-15,st.y+14);ctx.closePath();ctx.fill()}else{ctx.fillRect(st.x-13,st.y-19,26,38);ctx.fillStyle='#f8e6a3';ctx.fillRect(st.x-7,st.y-23,14,7)}ctx.shadowBlur=0;
  const scoreEl=document.getElementById('arcadeScore'),timeEl=document.getElementById('arcadeTime'),lifeEl=document.getElementById('arcadeLives');if(scoreEl)scoreEl.textContent=fmt(st.score);if(timeEl)timeEl.textContent=fmt(Math.floor(t))+' ثانیه';if(lifeEl)lifeEl.textContent=fmt(st.lives);
  if(st.dead&&t>=8){finishArcade();return}if(t>=180){finishArcade();return}st.raf=requestAnimationFrame(runArcadeFrame)}
async function finishArcade(){const st=arcadeState;if(!st||st.finishing)return;st.finishing=true;if(st.cleanup)st.cleanup();try{const d=await api('/api/games/arcade/finish','POST',{challenge_id:st.challengeId,score:st.score});renderProfile(d.profile);refreshProfile();stopArcade();showModal('نتیجه آرکید',`<div class="result-box"><strong>${d.won?'🏆 رکورد خوبی زدی!':'🚀 تلاش خوبی بود!'}</strong><p>امتیاز نهایی: ${fmt(d.score)}</p><h2>+${fmt(d.earned_xp)} XP</h2></div><button class="primary-btn" onclick="startArcade('${st.game}')">دوباره بازی کن</button>`)}catch(e){stopArcade();toast(e.message)}}

