// Memory game · responsive pair matching with three difficulty levels.
async function startMemory(pairs=null){
  if(pairs===null){
    if(memoryState?.timer)clearInterval(memoryState.timer);
    showModal('🧠 MEMORY MATRIX · حافظه تصویری',`<p class="helper">درجه سختی را انتخاب کن؛ با جفت‌های بیشتر، امتیاز XP بیشتری هم می‌گیری.</p><div class="memory-mode-grid"><button class="memory-mode" onclick="startMemory(6)"><b>🌱 آسان</b><span>۱۲ کارت · ۶ جفت</span><small>مناسب شروع</small></button><button class="memory-mode" onclick="startMemory(8)"><b>⚡ معمولی</b><span>۱۶ کارت · ۸ جفت</span><small>چالش استاندارد</small></button><button class="memory-mode" onclick="startMemory(12)"><b>🔥 سخت</b><span>۲۴ کارت · ۱۲ جفت</span><small>بیشترین XP</small></button></div>`);return;
  }
  try{
    const d=await api('/api/games/memory/start','POST',{pairs});
    if(memoryState?.timer)clearInterval(memoryState.timer);
    activeChallenge=d.challenge_id;memoryState={challenge_id:d.challenge_id,matched:new Set(),busy:false,attempts:0,pairs:0,pairsTotal:pairs,done:false};
    const cols=pairs===12?6:4;
    showModal('🧠 MEMORY MATRIX · حافظه تصویری',`<div class="memory-topline"><span>جفت‌ها <b id="memoryPairs">۰/${fmt(pairs)}</b></span><span>حرکت‌ها <b id="memoryAttempts">۰</b></span><span>زمان <b id="memoryTime">۰۰:۰۰</b></span></div><p class="helper">کارت‌ها را برگردان و همه ${fmt(pairs)} جفت را پیدا کن. با حرکت کمتر، XP بیشتری می‌گیری.</p><div id="memoryBoard" class="memory-board" style="grid-template-columns:repeat(${cols},minmax(0,1fr))">${Array.from({length:d.card_count},(_,i)=>`<button class="memory-card" id="memoryCard${i}" onclick="flipMemory(${i})" aria-label="کارت ${i+1}"><span class="memory-card-inner"><i class="memory-card-back">✦</i><b class="memory-card-front"></b></span></button>`).join('')}</div><div class="memory-footer"><span>🧩 ${fmt(pairs)} جفت · ${fmt(d.card_count)} کارت</span><button class="small-danger" onclick="startMemory(${pairs})">شروع دوباره</button></div>`);
    memoryState.startedAt=Date.now();memoryState.timer=setInterval(()=>{const el=document.getElementById('memoryTime');if(el&&memoryState)el.textContent=new Date(Date.now()-memoryState.startedAt).toISOString().slice(14,19)},1000);
  }catch(e){toast(e.message)}
}
async function flipMemory(index){
  const st=memoryState;if(!st||st.busy||st.done||st.matched.has(index))return;
  const card=document.getElementById('memoryCard'+index);if(!card||card.classList.contains('revealed'))return;
  st.busy=true;card.disabled=true;
  try{
    const d=await api('/api/games/memory/flip','POST',{challenge_id:st.challenge_id,index});
    for(const item of d.revealed||[]){const el=document.getElementById('memoryCard'+item.index);if(el){el.querySelector('.memory-card-front').textContent=item.symbol;el.classList.add('revealed')}}
    st.attempts=d.attempts||st.attempts;st.pairs=d.matched||st.pairs;
    const attempts=document.getElementById('memoryAttempts'),pairsEl=document.getElementById('memoryPairs');if(attempts)attempts.textContent=fmt(st.attempts);if(pairsEl)pairsEl.textContent=fmt(st.pairs)+'/'+fmt(st.pairsTotal);
    if(d.state==='one'){card.disabled=false;st.busy=false;return}
    if(d.state==='match'){
      for(const item of d.revealed||[]){st.matched.add(item.index);const el=document.getElementById('memoryCard'+item.index);if(el){el.classList.add('matched');el.disabled=true}}
    }
    if(d.finished){st.done=true;clearInterval(st.timer);if(d.profile)renderProfile(d.profile);refreshProfile();setTimeout(()=>showModal('🏆 MEMORY MATRIX · کامل شد!',`<div class="result-box"><strong>تمام ${fmt(st.pairsTotal)} جفت را پیدا کردی!</strong><p>${fmt(st.attempts)} حرکت · ${fmt(Math.round((Date.now()-st.startedAt)/1000))} ثانیه</p><h2>+${fmt(d.earned)} XP</h2><p>پاداش تکمیل: +${fmt(d.bonus_coins)} سکه</p></div><button class="primary-btn" onclick="startMemory(${st.pairsTotal})">مرحله جدید</button><button class="secondary-btn" onclick="startMemory()">تغییر سختی</button>`),500);return}
    if(d.state==='miss'){
      setTimeout(()=>{for(const item of d.revealed||[]){const el=document.getElementById('memoryCard'+item.index);if(el&&!st.matched.has(item.index)){el.classList.remove('revealed');el.disabled=false}}st.busy=false},850);
    }else st.busy=false;
  }catch(e){card.disabled=false;st.busy=false;toast(e.message)}
}
// NEON BREAKOUT — a real-time 2D brick-breaker arcade game.
async function startNeonBreakout(){
  try{
    const d=await api('/api/games/neon-breakout/start','POST',{});
    showModal('💠 NEON BREAKOUT · آرکید دوبعدی',`
      <div class="runner-hud breakout-hud"><span>مرحله <b id="breakoutLevel">۱/۳</b></span><span>❤️ <b id="breakoutLives">۳</b></span><span>💎 امتیاز <b id="breakoutScore">۰</b></span><span>🧱 <b id="breakoutBricks">۳۲</b></span><span>⚡ زنجیره <b id="breakoutCombo">۰</b></span></div>
      <canvas id="breakoutCanvas" class="breakout-canvas" width="360" height="500" aria-label="بازی دوبعدی نئون بریک‌اوت"></canvas>
      <div class="breakout-controls"><button onpointerdown="holdBreakout(-1)" onpointerup="stopBreakoutMove()" onpointerleave="stopBreakoutMove()" onpointercancel="stopBreakoutMove()">◀ چپ</button><button onclick="toggleBreakoutPause()" id="breakoutPauseBtn">توقف ⏸</button><button onpointerdown="holdBreakout(1)" onpointerup="stopBreakoutMove()" onpointerleave="stopBreakoutMove()" onpointercancel="stopBreakoutMove()">راست ▶</button></div>
      <p id="breakoutMessage" class="helper">آجرهای طلایی ممکن است پاورآپ بیندازند: پد عریض، قلب اضافه یا توپ آهسته. زنجیره ضربه‌ها امتیاز را بیشتر می‌کند.</p>
      <div id="breakoutResult"></div>`);
    const canvas=document.getElementById('breakoutCanvas');
    if(!canvas) return;
    breakoutState={challenge_id:d.challenge_id,canvas,ctx:canvas.getContext('2d'),score:0,lives:3,level:1,bricks:[],particles:[],powerups:[],combo:0,powerText:'',powerUntil:0,wideUntil:0,paused:false,finished:false,startedAt:performance.now(),lastFrame:0,moveDir:0,raf:0,ball:{x:180,y:430,vx:2.65,vy:-3.6,r:7},paddle:{x:135,y:462,w:90,h:12,baseW:90},resumeAt:0};
    buildBreakoutLevel();
    breakoutInputHandler=(event)=>{
      if(!breakoutState||breakoutState.finished)return;
      if(event.type==='keydown'){
        if(event.key==='ArrowLeft'||event.key==='a'||event.key==='A')breakoutState.moveDir=-1;
        if(event.key==='ArrowRight'||event.key==='d'||event.key==='D')breakoutState.moveDir=1;
        if(event.key===' '){event.preventDefault();toggleBreakoutPause();}
      }else if(event.type==='keyup'){
        if(['ArrowLeft','ArrowRight','a','A','d','D'].includes(event.key))breakoutState.moveDir=0;
      }
    };
    document.addEventListener('keydown',breakoutInputHandler);document.addEventListener('keyup',breakoutInputHandler);
    canvas.addEventListener('pointerdown',breakoutPointerMove);canvas.addEventListener('pointermove',breakoutPointerMove);
    drawBreakout();breakoutState.raf=requestAnimationFrame(breakoutLoop);
  }catch(e){toast(e.message)}
}
function buildBreakoutLevel(){
  const s=breakoutState;if(!s)return;s.bricks=[];s.powerups=[];s.paddle.w=s.paddle.baseW;
  const cols=8,rows=4,w=39,h=15,gap=5,startX=6,startY=65;
  for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)s.bricks.push({x:startX+c*(w+gap),y:startY+r*(h+gap),w,h,alive:true,gold:(r*cols+c+s.level)%9===0});
  s.ball={x:180,y:430,vx:(Math.random()<.5?-1:1)*2.65,vy:-3.6,r:7};s.paddle.x=135;
  s.resumeAt=performance.now()+350;
  updateBreakoutHud();
}
function breakoutPointerMove(e){
  const s=breakoutState;if(!s||s.finished)return;
  const rect=s.canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*(s.canvas.width/rect.width);
  s.paddle.x=Math.max(0,Math.min(360-s.paddle.w,x-s.paddle.w/2));
}
function holdBreakout(dir){if(breakoutState&&!breakoutState.finished)breakoutState.moveDir=dir}
function stopBreakoutMove(){if(breakoutState)breakoutState.moveDir=0}
function toggleBreakoutPause(){const s=breakoutState;if(!s||s.finished)return;s.paused=!s.paused;document.getElementById('breakoutPauseBtn').textContent=s.paused?'ادامه ▶':'توقف ⏸';}
function updateBreakoutHud(){
  const s=breakoutState;if(!s)return;
  const put=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};
  put('breakoutLevel',fmt(s.level)+'/۳');put('breakoutLives',fmt(s.lives));put('breakoutScore',fmt(s.score));put('breakoutBricks',fmt(s.bricks.filter(b=>b.alive).length));put('breakoutCombo',fmt(s.combo));
}
function drawBreakout(){
  const s=breakoutState;if(!s)return;const c=s.ctx,W=360,H=500;
  const bg=c.createLinearGradient(0,0,W,H);bg.addColorStop(0,s.level===1?'#101d40':s.level===2?'#25163d':'#32172e');bg.addColorStop(1,'#070a18');c.fillStyle=bg;c.fillRect(0,0,W,H);
  c.save();for(let i=0;i<48;i++){const x=(i*79+23)%W,y=(i*53+31)%H;c.globalAlpha=.18+(i%4)*.12;c.fillStyle=i%5===0?'#ffdf8a':'#9beeff';c.fillRect(x,y,1.5,1.5)}c.restore();
  c.strokeStyle='#78dfff12';c.lineWidth=1;for(let x=0;x<W;x+=30){c.beginPath();c.moveTo(x,0);c.lineTo(x,H);c.stroke()}for(let y=0;y<H;y+=30){c.beginPath();c.moveTo(0,y);c.lineTo(W,y);c.stroke()}
  c.save();c.globalAlpha=.18;c.strokeStyle=s.level===3?'#ff86c5':'#72e7ff';c.lineWidth=2;c.beginPath();c.arc(180,110,90,0,Math.PI*2);c.stroke();c.beginPath();c.arc(180,110,120,0,Math.PI*2);c.stroke();c.restore();
  for(const b of s.bricks){if(!b.alive)continue;const color=b.gold?'#ffca55':(b.y<90?'#b28cff':b.y<110?'#4edaf1':'#3a92d2');c.save();c.shadowBlur=b.gold?18:10;c.shadowColor=color;c.fillStyle=color;c.beginPath();c.roundRect(b.x,b.y,b.w,b.h,5);c.fill();c.fillStyle='#ffffff66';c.fillRect(b.x+4,b.y+3,b.w-8,2);c.fillStyle='#08132455';c.fillRect(b.x+4,b.y+b.h-4,b.w-8,1);c.restore()}
  for(const power of s.powerups){c.save();c.shadowBlur=15;c.shadowColor=power.type==='wide'?'#5ce9ff':power.type==='life'?'#ff7c9f':'#c69aff';c.fillStyle=power.type==='wide'?'#51dff5':power.type==='life'?'#ff739b':'#b38cff';c.beginPath();c.roundRect(power.x-10,power.y-10,20,20,6);c.fill();c.fillStyle='#081324';c.font='bold 12px sans-serif';c.textAlign='center';c.fillText(power.type==='wide'?'↔':power.type==='life'?'♥':'⌁',power.x,power.y+4);c.restore()}
  for(const particle of s.particles){c.save();c.globalAlpha=Math.max(0,particle.life/24);c.fillStyle=particle.color;c.shadowBlur=8;c.shadowColor=particle.color;c.beginPath();c.arc(particle.x,particle.y,particle.size,0,Math.PI*2);c.fill();c.restore()}
  c.save();c.shadowColor='#54e8ff';c.shadowBlur=25;c.fillStyle='#63eaff';c.beginPath();c.roundRect(s.paddle.x,s.paddle.y,s.paddle.w,s.paddle.h,7);c.fill();c.restore();
  c.save();c.shadowColor='#ffe58c';c.shadowBlur=22;c.fillStyle='#fff6c6';c.beginPath();c.arc(s.ball.x,s.ball.y,s.ball.r,0,Math.PI*2);c.fill();c.restore();
  c.fillStyle='#d4e8ff99';c.font='10px sans-serif';c.textAlign='center';c.fillText(['NEON CITY','CYBER CORE','NOVA ZONE'][s.level-1]+'  ·  LEVEL '+s.level,W/2,25);
  if(s.powerText&&performance.now()<s.powerUntil){c.fillStyle='#fff';c.font='bold 12px sans-serif';c.shadowColor='#62eaff';c.shadowBlur=12;c.fillText(s.powerText,W/2,48);c.shadowBlur=0}
  if(s.paused){c.fillStyle='#050817bb';c.fillRect(0,0,W,H);c.fillStyle='#fff';c.font='bold 25px sans-serif';c.fillText('PAUSED',W/2,H/2)}
}
function burstBreakout(x,y,color,count=10){const s=breakoutState;if(!s)return;for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,speed=1+Math.random()*3;s.particles.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,life:14+Math.random()*18,size:1.5+Math.random()*2.5,color})}}
function breakoutLoop(now){
  const s=breakoutState;if(!s||s.finished)return;
  const dt=Math.min(2.2,Math.max(.5,(now-(s.lastFrame||now))/16.67));s.lastFrame=now;
  if(!s.paused&&now>=s.resumeAt){
    const b=s.ball,p=s.paddle,W=360,H=500;
    p.x=Math.max(0,Math.min(W-p.w,p.x+s.moveDir*6.4*dt));
    if(s.wideUntil&&now>s.wideUntil){p.w=p.baseW;s.wideUntil=0}
    s.particles=s.particles.filter(q=>q.life>0);for(const q of s.particles){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vx*=.985;q.vy=q.vy*.985+.035*dt;q.life-=dt}
    for(let i=s.powerups.length-1;i>=0;i--){const power=s.powerups[i];power.y+=2.2*dt;if(power.y>=p.y-6&&power.y<=p.y+p.h+8&&power.x>=p.x-5&&power.x<=p.x+p.w+5){if(power.type==='wide'){p.w=Math.min(145,p.baseW+45);s.wideUntil=now+8500;s.powerText='پد تقویت‌شده'}else if(power.type==='life'){s.lives=Math.min(5,s.lives+1);s.powerText='یک قلب اضافه'}else{b.vx*=.78;b.vy*=.78;s.powerText='سرعت توپ کاهش یافت'}s.powerUntil=now+1800;burstBreakout(power.x,power.y,'#ffe18b',14);s.powerups.splice(i,1);updateBreakoutHud()}else if(power.y>H+20)s.powerups.splice(i,1)}
    b.x+=b.vx*dt;b.y+=b.vy*dt;
    if(b.x-b.r<0){b.x=b.r;b.vx=Math.abs(b.vx)}if(b.x+b.r>W){b.x=W-b.r;b.vx=-Math.abs(b.vx)}if(b.y-b.r<0){b.y=b.r;b.vy=Math.abs(b.vy)}
    if(b.vy>0&&b.y+b.r>=p.y&&b.y-b.r<=p.y+p.h&&b.x>=p.x-3&&b.x<=p.x+p.w+3){
      const hit=(b.x-(p.x+p.w/2))/(p.w/2);b.vx=hit*4.6;b.vy=-Math.max(3.2,Math.sqrt(Math.max(8, b.vx*b.vx+14)));b.y=p.y-b.r-1;
    }
    for(const brick of s.bricks){if(!brick.alive)continue;if(b.x+b.r>brick.x&&b.x-b.r<brick.x+brick.w&&b.y+b.r>brick.y&&b.y-b.r<brick.y+brick.h){brick.alive=false;b.vy*=-1;s.combo=Math.min(99,s.combo+1);const color=brick.gold?'#ffdb6e':brick.y<90?'#b28cff':'#5ce9ff';s.score+=(brick.gold?100:40)+Math.min(80,s.combo*4);burstBreakout(b.x,b.y,color,brick.gold?18:9);if(Math.random()<(brick.gold?.45:.12))s.powerups.push({x:brick.x+brick.w/2,y:brick.y+brick.h/2,vy:2,type:['wide','life','slow'][Math.floor(Math.random()*3)]});break}}
    if(b.y-b.r>H){s.lives--;s.combo=0;burstBreakout(p.x+p.w/2,p.y,'#ff789f',18);updateBreakoutHud();if(s.lives<=0){finishBreakout();return}s.ball={x:180,y:430,vx:(Math.random()<.5?-1:1)*2.6,vy:-3.7,r:7};s.resumeAt=now+650;}
    if(s.bricks.every(x=>!x.alive)){
      if(s.level>=3){finishBreakout();return}
      s.level++;buildBreakoutLevel();document.getElementById('breakoutMessage').textContent='مرحله بعدی شروع شد؛ سرعت کمی بیشتر شده!';
      s.ball.vx*=1.08;s.ball.vy*=1.08;
    }
  }
  drawBreakout();updateBreakoutHud();s.raf=requestAnimationFrame(breakoutLoop);
}
function stopBreakoutLoop(){if(breakoutState?.raf)cancelAnimationFrame(breakoutState.raf);if(breakoutInputHandler){document.removeEventListener('keydown',breakoutInputHandler);document.removeEventListener('keyup',breakoutInputHandler)}breakoutInputHandler=null;breakoutState=null}
async function finishBreakout(){
  const s=breakoutState;if(!s||s.finished)return;s.finished=true;if(s.raf)cancelAnimationFrame(s.raf);
  const duration_ms=Math.max(5000,Math.round(performance.now()-s.startedAt));
  try{
    const d=await api('/api/games/neon-breakout/finish','POST',{challenge_id:s.challenge_id,score:s.score,duration_ms});
    renderProfile(d.profile);refreshProfile();
    if(breakoutState!==s)return;
    const area=document.getElementById('gameArea');
    area.innerHTML=`<div class="result-box"><strong>${d.won?'🏆 آرکید را فتح کردی!':'💫 بازی تمام شد!'}</strong><p>امتیاز نهایی: ${fmt(d.score)} · زمان: ${fmt(d.duration_seconds)} ثانیه</p><h2>+${fmt(d.earned)} XP</h2><p>جایزه اضافه: +${fmt(d.bonus_coins)} سکه</p></div><button class="primary-btn" onclick="startNeonBreakout()">بازی دوباره</button>`;
  }catch(e){if(breakoutState!==s)return;const area=document.getElementById('gameArea');if(area)area.innerHTML=`<div class="result-box"><strong>ثبت نتیجه ناموفق بود</strong><p>${escapeHtml(e.message)}</p></div><button class="primary-btn" onclick="startNeonBreakout()">شروع دوباره</button>`}
}

// Daily rewards and wheel
async function claimDaily(){try{const d=await api('/api/daily-claim','POST',{});if(d.ok){renderProfile(d.profile);toast('🎁 '+fmt(d.reward)+' XP دریافت کردی!');const b=document.getElementById('dailyBtn');b.textContent='دریافت شد';b.disabled=true;refreshProfile()}else toast(d.message)}catch(e){toast(e.message)}}
async function loadWheelStatus(){try{const d=await api('/api/wheel');const info=document.getElementById('wheelInfo'),button=document.getElementById('wheelButton');if(info)info.textContent=d.free_ticket?'🎁 اول هر روز رایگان · سپس ۱۰، ۳۰، ۵۰، ۹۰، ۱۲۰ و بعد هر دور +۳۰ سکه':`چرخش ${fmt(d.spins_today+1)} امروز · هزینه ${fmt(d.next_cost)} سکه`;if(button){button.textContent=d.free_ticket?'چرخش رایگان':`چرخش · ${fmt(d.next_cost)} 🪙`;button.disabled=wheelBusy||(!d.free_ticket&&d.coins<d.next_cost);button.title=button.disabled&&!d.free_ticket?'موجودی کافی نیست':''}}catch(e){toast(e.message)}}
async function spinWheel(){if(wheelBusy)return;wheelBusy=true;const button=document.getElementById('wheelButton');if(button){button.disabled=true;button.textContent='در حال چرخش...'}try{const d=await api('/api/wheel/spin','POST',{});renderProfile(d.profile);const disc=document.getElementById('wheelDisc'),prizes=[5,10,15,20,30,50,75,100],target=prizes.indexOf(d.reward);wheelRotation+=360*5+(target<0?0:target*45);if(disc){disc.style.transform=`rotate(${wheelRotation}deg)`;await new Promise(resolve=>setTimeout(resolve,2300))}toast(`🎰 ${d.is_free?'چرخش رایگان':'هزینه '+fmt(d.cost)+' سکه'} · جایزه ${fmt(d.reward)} سکه!`);await loadWheelStatus()}catch(e){toast(e.message);await loadWheelStatus()}finally{wheelBusy=false;await loadWheelStatus()}}

// Competition
async function showPublicProfile(id){
  try{
    const d=await api(`/api/users/${id}/public-profile`),p=d.profile,c=d.cosmetics||{};
    const character=c[String(p.equipped_character_id||p.equipped_avatar_id)],frame=c[String(p.equipped_frame_id)],badge=c[String(p.equipped_badge_id)],gift=c[String(p.equipped_gift_id)],showcase=c[String(p.equipped_showcase_id)];
    const portrait=p.photo_url?`<img src="${escapeHtml(p.photo_url)}" alt="">`:`<span>${escapeHtml(initials(p.name))}</span>`;
    const ring=frame?.image_url?`<img class="frame-ring" src="${escapeHtml(frame.image_url)}" alt="قاب پروفایل">`:'';
    const chips=[badge,gift,showcase].filter(Boolean).map(x=>`<span class="equipped-chip">${x.image_url?`<img src="${escapeHtml(x.image_url)}" alt="">`:''}${escapeHtml(x.name)}</span>`).join('');
    const characterImage=p.owner_character_url||p.custom_character_url||character?.image_url;const characterName=p.owner_character_url?'کاراکتر اختصاصی مالک':(p.custom_character_url?'کاراکتر شخصی':(character?.name||''));
    const characterStage=characterImage?`<div class="character-stage public-character-stage ${p.owner_character_url?'owner-character-stage':''}"><div class="character-stage-label"><span>${p.owner_character_url?'INTERACTIVE 3D OWNER':'PLAYER MODEL'}</span><b>${escapeHtml(characterName)}</b></div><div class="character-render">${/\.glb(?:[?#]|$)/i.test(characterImage)?`<model-viewer class="character-model-viewer" src="${escapeHtml(characterImage)}" alt="کاراکتر سه‌بعدی" camera-controls auto-rotate rotation-per-second="10deg" interaction-prompt="none" shadow-intensity="1.25" exposure="1.05" camera-target="${p.owner_character_url?'0m 2.85m 0m':'0m 2.25m 0m'}" camera-orbit="${p.owner_character_url?'0deg 76deg 9.2m':'0deg 78deg 6.1m'}" min-camera-orbit="${p.owner_character_url?'auto 42deg 7m':'auto 35deg 4.2m'}" max-camera-orbit="${p.owner_character_url?'auto 112deg 13m':'auto 105deg 8m'}" environment-image="neutral"></model-viewer>`:`<img src="${escapeHtml(characterImage)}" alt="کاراکتر نمایشی">`}</div><div class="model-hint">مدل را بکش تا از زاویه‌های مختلف ببینی.</div></div>`:'';
    showModal('پروفایل بازیکن',`<div class="public-profile"><div class="public-avatar avatar-frame-host">${ring}<div class="avatar-portrait">${portrait}</div></div><h3>${escapeHtml(p.name)} ${identityMarks(p)} ${vipMark(p)}</h3><p>${escapeHtml(p.league)} · سطح ${fmt(p.level)} · ${p.vip_tier&&p.vip_tier!=='none'?escapeHtml(p.vip_tier.toUpperCase()):'کاربر عادی'}</p>${characterStage}<div class="profile-grid"><div><b>${fmt(p.wins)}</b><small>برد</small></div><div><b>${fmt(p.games)}</b><small>بازی</small></div><div><b>${fmt(p.xp)}</b><small>XP</small></div></div>${chips?`<div class="public-cosmetics">${chips}</div>`:''}</div>`);
    const publicImg=document.querySelector('#gameArea .public-character-stage .character-render img');
    publicImg?.addEventListener('error',()=>{const render=publicImg.closest('.character-render');if(render)render.innerHTML='<div class="character-image-fallback">تصویر کاراکتر بارگذاری نشد.</div>'},{once:true});
  }catch(e){toast(e.message)}
}
async function loadLeaderboard(period='all',btn=null){try{const d=await api('/api/leaderboard?period='+period);document.getElementById('myRank').textContent='#'+fmt(d.my_rank);document.getElementById('leaderboard').innerHTML=d.users.map(u=>`<button class="rank-row ${u.is_me?'me':''}" onclick="showPublicProfile(${u.id})"><div class="rank-no">${u.rank<=3?['🥇','🥈','🥉'][u.rank-1]:fmt(u.rank)}</div><div class="rank-name">${escapeHtml(u.name)} ${identityMarks(u)}${u.is_me?' (تو)':''}</div><div class="rank-meta"><b>${fmt(u.xp)} XP</b><small>${escapeHtml(u.league)}</small></div></button>`).join('')||'<p class="helper">برای این بازه هنوز امتیازی ثبت نشده.</p>';if(btn){document.querySelectorAll('.period-tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}}catch(e){toast(e.message)}}
