async function joinLiveArena(){try{const d=await api('/api/arena/matchmaking/join','POST',{game:'math'});if(d.match_id){liveArenaMatchId=d.match_id;pollLiveMatch(d.match_id)}else{document.getElementById('liveArenaStatus').innerHTML='<p class="helper">🔎 در حال پیدا کردن حریف…</p>';if(liveArenaPoll)clearInterval(liveArenaPoll);liveArenaPoll=setInterval(loadLiveMatchmaking,2500)}}catch(e){toast(e.message)}}
async function cancelLiveArena(){try{await api('/api/arena/matchmaking/cancel','POST',{});if(liveArenaPoll)clearInterval(liveArenaPoll);liveArenaPoll=null;liveArenaMatchId=null;document.getElementById('liveArenaStatus').innerHTML='<p class="helper">جست‌وجو لغو شد.</p>'}catch(e){toast(e.message)}}
async function pollLiveMatch(id){if(liveArenaPoll)clearInterval(liveArenaPoll);const tick=async()=>{try{const d=await api(`/api/arena/matches/${id}`);const state=document.getElementById('liveArenaStatus');if(!state)return;if(d.status==='playing'){if(!state.querySelector('.live-question'))state.innerHTML=`<div class="live-question"><small id="liveOpponentStatus"></small><b>${escapeHtml(d.question)}</b><input id="liveAnswer" type="number" placeholder="پاسخ تو"><button id="liveAnswerButton" onclick="submitLiveAnswer(${id})">ثبت پاسخ</button><p class="helper">هر بازیکن یک پاسخ دارد؛ نتیجه بعد از ثبت هر دو پاسخ اعلام می‌شود.</p></div>`;const status=state.querySelector('#liveOpponentStatus');if(status)status.textContent=d.opponent_answered?'حریف پاسخ داده؛ منتظر نتیجه':'در انتظار پاسخ حریف';const input=state.querySelector('#liveAnswer'),button=state.querySelector('#liveAnswerButton');if(d.my_answered&&input){input.disabled=true;if(button)button.disabled=true}}else if(d.status==='completed'){state.innerHTML=`<div class="result-box"><b>${d.winner_id?`برنده: ${fmt(d.winner_id)}`:'مسابقه مساوی شد'}</b><p>${d.is_winner===true?'🏆 پیروز شدی!':d.is_winner===false?'این دور را باختی.':'نتیجه مساوی بود.'}</p></div>`;clearInterval(liveArenaPoll);liveArenaPoll=null;refreshProfile();loadSeasonHub()}else{state.innerHTML='<p class="helper">زمان مسابقه تمام شد یا مسابقه لغو شد.</p>';clearInterval(liveArenaPoll);liveArenaPoll=null}}catch(e){state.innerHTML=`<p class="helper">${escapeHtml(e.message)}</p>`;clearInterval(liveArenaPoll);liveArenaPoll=null}};await tick();if(!liveArenaPoll&&document.getElementById('liveArenaStatus')?.querySelector('.live-question'))liveArenaPoll=setInterval(tick,1800)}
async function submitLiveAnswer(id){const answer=Number(document.getElementById('liveAnswer').value);if(!Number.isInteger(answer)){toast('پاسخ عددی وارد کن.');return}try{await api(`/api/arena/matches/${id}/answer`,'POST',{answer});toast('پاسخ ثبت شد. منتظر حریف بمان.');pollLiveMatch(id)}catch(e){toast(e.message)}}
function renderClans(d,battles=[]){
  const mine=document.getElementById('myClan');
  mine.innerHTML=d.my_clan?`<div class="flex-between"><b>👥 ${escapeHtml(d.my_clan.name)}</b><span>سطح ${fmt(d.my_clan.level||1)} · ${fmt(d.my_clan.xp||0)} XP · ${fmt(d.my_clan.members)} عضو · ${escapeHtml(d.my_clan.role)}</span></div><p>${escapeHtml(d.my_clan.description||'کلن فعال تو')}</p><div class="clan-actions"><button onclick="viewClanMembers(${d.my_clan.id})">مشاهده اعضا</button><button class="small-danger" onclick="leaveClan()">خروج از کلن</button></div>${d.my_clan.role==='owner'||d.my_clan.role==='leader'?`<div class="clan-battle-create"><select id="clanOpponent">${d.clans.filter(c=>c.id!==d.my_clan.id).map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}</select><button onclick="challengeClan()" ${d.clans.length<2?'disabled':''}>⚔️ دعوت به نبرد کلنی</button></div>`:''}`:'هنوز عضو کلنی نیستی؛ یک کلن بساز یا به یکی بپیوند.';
  document.getElementById('clanList').innerHTML=d.clans.map(c=>`<div class="list-card"><div><b>${escapeHtml(c.name)} ${identityMarks({is_owner:c.owner_is_owner,is_verified:c.owner_verified})}</b><small>سطح ${fmt(c.level||1)} · ${fmt(c.xp||0)} XP · ${fmt(c.members)} عضو · رهبر: ${escapeHtml(c.owner_name||'بازیکن')} · ${escapeHtml(c.description)}</small></div><div class="list-actions"><button onclick="viewClanMembers(${c.id})">اعضا</button>${!d.my_clan?`<button onclick="joinClan(${c.id})">عضویت</button>`:''}</div></div>`).join('')||'<p class="helper">هنوز کلنی ساخته نشده.</p>';
  renderClanBattles(battles,d.my_clan?.id);
}
async function viewClanMembers(id){try{const d=await api(`/api/clans/${id}/members`),canManage=currentProfile?.id===d.clan.owner_id;const items=d.members.map(m=>`<div class="clan-member-row"><div><b>${m.online?'🟢':'⚫'} ${escapeHtml(m.name)} ${identityMarks(m)} ${vipMark(m)}</b><small>${escapeHtml(m.role)} · سطح ${fmt(m.level)} · ${escapeHtml(m.league)} · ID ${m.id}</small></div><div class="list-actions"><button onclick="showPublicProfile(${m.id})">پروفایل</button>${canManage&&m.id!==d.clan.owner_id?`<button onclick="setClanRole(${id},${m.id},'${m.role==='leader'?'member':'leader'}')">${m.role==='leader'?'برداشتن فرماندهی':'فرمانده'}</button><button class="small-danger" onclick="removeClanMember(${id},${m.id})">اخراج</button>`:''}</div></div>`).join('');showModal(`👥 اعضای ${escapeHtml(d.clan.name)}`,`<div class="clan-members">${items||'<p class="helper">عضوی ثبت نشده است.</p>'}</div>`)}catch(e){toast(e.message)}}
async function setClanRole(clanId,userId,role){try{await api(`/api/clans/${clanId}/members/${userId}/role`,'PUT',{role});toast('نقش عضو تغییر کرد.');viewClanMembers(clanId)}catch(e){toast(e.message)}}
async function removeClanMember(clanId,userId){if(!confirm('این عضو از کلن اخراج شود؟'))return;try{await api(`/api/clans/${clanId}/members/${userId}`,'DELETE');toast('عضو از کلن خارج شد.');viewClanMembers(clanId);loadCompetition()}catch(e){toast(e.message)}}
async function challengeClan(){const opponent_clan_id=Number(document.getElementById('clanOpponent')?.value);if(!opponent_clan_id){toast('یک کلن حریف انتخاب کن.');return}try{await api('/api/clan-battles','POST',{opponent_clan_id});toast('دعوت نبرد کلنی ارسال شد.');loadCompetition()}catch(e){toast(e.message)}}
function renderClanBattles(items,myClanId){const el=document.getElementById('clanBattleList');if(!el)return;el.innerHTML=items.map(b=>{const incoming=Number(b.opponent_clan_id)===Number(myClanId);const a=clanCache.find(x=>x.id===b.challenger_clan_id)?.name||('کلن #'+b.challenger_clan_id),o=clanCache.find(x=>x.id===b.opponent_clan_id)?.name||('کلن #'+b.opponent_clan_id);const score=`${fmt(b.challenger_score)} - ${fmt(b.opponent_score)}`;const status=b.status==='active'?`نبرد فعال · ${score} · پایان ${new Date(b.ends_at).toLocaleString('fa-IR')}`:b.status==='pending'?'دعوت در انتظار پاسخ':b.status==='completed'?`نتیجه نهایی ${score} · ${b.winner_clan_id?(Number(b.winner_clan_id)===Number(b.challenger_clan_id)?'برنده: '+escapeHtml(a):'برنده: '+escapeHtml(o)):'مساوی'}`:'دعوت رد شد';return `<div class="list-card"><div><b>⚔️ ${escapeHtml(a)} × ${escapeHtml(o)}</b><small>${status}</small></div><div class="list-actions">${b.status==='pending'&&incoming?`<button onclick="respondClanBattle(${b.id},true)">قبول</button><button class="small-danger" onclick="respondClanBattle(${b.id},false)">رد</button>`:''}</div></div>`}).join('')||'<p class="helper">هنوز نبرد کلنی‌ای ثبت نشده است.</p>'}
async function respondClanBattle(id,accept){try{await api(`/api/clan-battles/${id}/respond`,'POST',{accept});toast(accept?'نبرد ۲۴ ساعته آغاز شد.':'دعوت نبرد رد شد.');loadCompetition()}catch(e){toast(e.message)}}
async function createClan(){const name=document.getElementById('clanName').value.trim(),description=document.getElementById('clanDescription').value.trim();if(!name){toast('نام کلن را وارد کن.');return}try{await api('/api/clans/create','POST',{name,description});toast('کلن ساخته شد.');document.getElementById('clanName').value='';loadCompetition()}catch(e){toast(e.message)}}
async function joinClan(id){try{await api('/api/clans/join','POST',{clan_id:id});toast('به کلن پیوستی.');loadCompetition()}catch(e){toast(e.message)}}
async function leaveClan(){try{await api('/api/clans/leave','POST',{});toast('از کلن خارج شدی.');loadCompetition()}catch(e){toast(e.message)}}
async function sendFriendChallenge(){const target_id=Number(document.getElementById('friendId').value),game=document.getElementById('friendGame').value;if(!target_id){toast('شناسه عددی دوست را وارد کن.');return}try{await api('/api/friends/challenge','POST',{target_id,game});toast('دعوت چالش ارسال شد.');document.getElementById('friendId').value='';loadCompetition()}catch(e){toast(e.message)}}
function renderFriends(data){const list=document.getElementById('friendList'),requests=document.getElementById('friendRequests');if(list)list.innerHTML=(data.friends||[]).map(f=>`<div class="list-card"><div><b>${f.online?'🟢':'⚫'} ${escapeHtml(f.name)} ${identityMarks(f)} ${vipMark(f)}</b><small>ID: ${f.id} · ${f.online?'آنلاین':'آفلاین'}</small></div><div class="list-actions"><button onclick="startBotDm(${f.id})">چت در ربات</button><button onclick="document.getElementById('friendId').value='${f.id}'">چالش</button><button class="small-danger" onclick="removeFriend(${f.id})">حذف</button></div></div>`).join('')||'<p class="helper">هنوز دوستی نداری. با شناسه عددی دوستت درخواست بفرست.</p>';if(requests)requests.innerHTML=(data.requests||[]).map(r=>`<div class="list-card"><div><b>${r.incoming?'درخواست دوستی ورودی':'درخواست ارسال‌شده'}</b><small>${escapeHtml(r.other_name)} · ID ${r.other_id}</small></div>${r.incoming?`<div class="list-actions"><button onclick="respondFriendRequest(${r.id},true)">قبول</button><button class="small-danger" onclick="respondFriendRequest(${r.id},false)">رد</button></div>`:'<span class="status-tag">در انتظار</span>'}</div>`).join('')}
async function sendFriendRequest(){const target_id=Number(document.getElementById('friendAddId').value);if(!target_id){toast('شناسه عددی را وارد کن.');return}try{const d=await api('/api/friends/request','POST',{target_id});toast(d.accepted?'درخواست دوطرفه بود؛ دوست شدید.':'درخواست دوستی ارسال شد.');document.getElementById('friendAddId').value='';loadCompetition()}catch(e){toast(e.message)}}
async function respondFriendRequest(id,accept){try{await api(`/api/friends/request/${id}/respond`,'POST',{accept});toast(accept?'درخواست دوستی پذیرفته شد.':'درخواست رد شد.');loadCompetition()}catch(e){toast(e.message)}}
async function removeFriend(id){if(!confirm('این کاربر از فهرست دوستان حذف شود؟'))return;try{await api(`/api/friends/${id}`,'DELETE');toast('دوست حذف شد.');loadCompetition()}catch(e){toast(e.message)}}
function startBotDm(id){const match=referralLink.match(/^https:\/\/t\.me\/([^?]+)/);if(!match){toast('ربات را باز کن و دستور /dm '+id+' را بفرست.');return}const link=`https://t.me/${match[1]}?start=dm_${id}`;if(tg?.openTelegramLink)tg.openTelegramLink(link);else window.open(link,'_blank');}
function renderEvents(items){const el=document.getElementById('eventList');if(!el)return;el.innerHTML=(items||[]).map(e=>`<div class="list-card event-card"><div><b>🎉 ${escapeHtml(e.title)}</b><small>${escapeHtml(e.description||'رویداد ویژه آرنا')} · +${fmt(e.bonus_xp)} XP اضافه برای هر بازی واجد شرایط · پایان ${new Date(e.ends_at).toLocaleString('fa-IR')}</small></div><span class="status-tag">فعال</span></div>`).join('')||'<p class="helper">فعلاً رویداد فعالی وجود ندارد.</p>'}
function renderFriendChallenges(items){document.getElementById('friendChallenges').innerHTML=items.map(x=>`<div class="list-card"><div><b>⚔️ چالش #${x.id}</b><small>${x.incoming?'از کاربر '+x.sender_id:'به کاربر '+x.target_id} · ${escapeHtml(gameLabel(x.game))} · ${escapeHtml(x.status)}</small>${x.status==='completed'?`<small>نتیجه: ${x.sender_score} - ${x.target_score} · برنده ${x.winner_id||'مساوی'}</small>`:''}</div><div class="list-actions">${x.status==='pending'&&x.incoming?`<button onclick="respondFriend(${x.id},true)">قبول</button><button class="small-danger" onclick="respondFriend(${x.id},false)">رد</button>`:''}${x.status==='accepted'?`<button onclick="playFriendChallenge(${x.id})">بازی کن</button>`:''}</div></div>`).join('')||'<p class="helper">دعوت فعالی نداری.</p>'}
async function respondFriend(id,accept){try{await api('/api/friends/challenges/respond','POST',{challenge_id:id,accept});loadCompetition()}catch(e){toast(e.message)}}
async function playFriendChallenge(id){try{const d=await api(`/api/friends/challenges/${id}/prompt`);const seq=d.sequence||[];const preview=seq.length?`<div id="friendMemorySequence" class="memory-sequence">${seq.join('　')}</div>`:'';const placeholder=seq.length?'نمادها را با | جدا کن':'پاسخت را وارد کن';showModal('⚔️ چالش دوستان',`<p class="helper">${escapeHtml(d.question)}</p>${preview}<div id="friendAnswerBox" class="${seq.length?'hidden':''}"><input id="friendAnswer" class="friend-answer" placeholder="${placeholder}"><button class="primary-btn" onclick="submitFriendPlay(${id})">ثبت پاسخ</button></div>${seq.length?'<p class="helper">ترتیب را به خاطر بسپار؛ سه ثانیه دیگر پنهان می‌شود.</p>':''}`);if(seq.length){setTimeout(()=>{const el=document.getElementById('friendMemorySequence');if(el)el.textContent='؟　؟　؟';document.getElementById('friendAnswerBox')?.classList.remove('hidden')},3000)}}catch(e){toast(e.message)}}
async function submitFriendPlay(id){const answer=document.getElementById('friendAnswer')?.value.trim();if(!answer){toast('پاسخ را وارد کن.');return}try{const d=await api('/api/friends/challenges/play','POST',{challenge_id:id,answer});closeModal();toast(d.status==='completed'?(d.winner_id?'چالش تمام شد؛ برنده مشخص شد.':'چالش مساوی شد.'):'پاسخت ثبت شد؛ منتظر حریف بمان.');loadCompetition()}catch(e){toast(e.message)}}
function renderTournaments(items){document.getElementById('tournamentList').innerHTML=items.map(t=>`<div class="list-card"><div><b>🏆 ${escapeHtml(t.name)}</b><small>${escapeHtml(t.game)} · جایزه ${fmt(t.prize_coins)} سکه · ${fmt(t.players)}/${fmt(t.max_players)} نفر · ${escapeHtml(t.status)}</small></div>${t.joined?'<span class="status-tag">ثبت‌نام شد</span>':t.status==='open'?`<button onclick="joinTournament(${t.id})">شرکت می‌کنم</button>`:''}</div>${t.bracket?`<div class="bracket-public">${t.bracket.map((r,i)=>`دور ${fmt(i+1)}: ${r.map(m=>`${m.p1} vs ${m.p2||'استراحت'} ${m.winner?'→ '+m.winner:''}`).join(' | ')}`).join('<br>')}</div>`:''}`).join('')||'<p class="helper">فعلاً تورنمنتی برگزار نمی‌شود.</p>'}
async function joinTournament(id){try{await api(`/api/tournaments/${id}/join`,'POST',{});toast('ثبت‌نام تورنمنت انجام شد.');loadCompetition()}catch(e){toast(e.message)}}

// Store, inventory and profile appearance
function categoryLabel(c){return ({avatar:'کاراکتر سه‌بعدی',character:'کاراکتر سه‌بعدی',frame:'قاب دور عکس',badge:'نشان',gift:'هدیه مالک',pack:'بسته جایزه',skin:'کاراکتر سه‌بعدی',item:'آیتم'})[c]||c}
function renderInventory(items){profileInventory=items||[];document.getElementById('inventoryList').innerHTML=profileInventory.map(x=>{const action=x.is_pack?`<button onclick="openPack(${x.product_id})">بازکردن بسته</button>`:(['character','frame','badge','gift','showcase'].includes(x.equip_slot)?`<button onclick="equipProduct(${x.product_id})">${x.equipped?'برداشتن':'انتخاب در پروفایل'}</button>`:'');return `<div class="list-card inventory-row"><div>${x.image_url?`<img class="mini-cosmetic" src="${escapeHtml(x.image_url)}" alt="">`:''}<div><b>${escapeHtml(x.name)}</b><small>${categoryLabel(x.category)} · ${escapeHtml(x.rarity||'')} · تعداد ${fmt(x.quantity)}${x.reward_only?' · جایزه مالک':''}</small></div></div>${action}</div>`}).join('')||'<p class="helper">هنوز آیتمی نخریدی یا جایزه نگرفتی.</p>';applyEquippedCosmetics()}
async function loadShop(){try{const [p,i]=await Promise.all([api('/api/shop/products'),api('/api/shop/inventory')]);document.getElementById('shopProducts').innerHTML=p.products.map(x=>`<div class="product-card"><div class="product-art">${x.image_url?`<img src="${escapeHtml(x.image_url)}" alt="">`:({'character':'🧍','avatar':'🧍','skin':'🧍','badge':'🏅','frame':'🖼️'}[x.category]||'💎')}</div><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.description)}</small><span class="rarity ${escapeHtml(x.rarity)}">${escapeHtml(x.rarity)}</span><div class="product-buy"><strong>🪙 ${fmt(x.price_coins)}</strong><button onclick="buyProduct(${x.id})">خرید</button></div></div>`).join('')||'<p class="helper">فروشگاه فعلاً خالی است.</p>';renderInventory(i.items)}catch(e){toast(e.message)}}
async function buyProduct(id){try{const d=await api('/api/shop/buy','POST',{product_id:id});renderProfile(d.profile);toast(d.message);loadShop()}catch(e){toast(e.message)}}
async function equipProduct(id){try{const d=await api('/api/profile/equip','POST',{product_id:id});renderProfile(d.profile);toast(d.equipped?'آیتم در پروفایلت نمایش داده می‌شود.':'آیتم از پروفایلت برداشته شد.');loadShop()}catch(e){toast(e.message)}}
async function openPack(id){if(!confirm('این بسته باز شود و محتویاتش به کوله‌پشتی اضافه شود؟'))return;try{const d=await api('/api/shop/packs/open','POST',{product_id:id});toast(d.message+' '+d.received.map(x=>x.name+' ×'+x.quantity).join('، '));loadShop();loadProfileExtras()}catch(e){toast(e.message)}}
async function uploadMyCharacter(){const input=document.getElementById('customCharacterFile'),file=input?.files?.[0];if(!file){toast('فایل GLB یا تصویر کاراکتر را انتخاب کن.');return}const isGlb=file.name.toLowerCase().endsWith('.glb')&&file.size<=16*1024*1024;const isImage=['image/png','image/jpeg','image/webp'].includes(file.type)&&file.size<=4*1024*1024;if(!isGlb&&!isImage){toast('مدل GLB تا ۱۶ مگابایت یا تصویر PNG/JPG/WEBP تا ۴ مگابایت انتخاب کن.');return}try{const form=new FormData();form.append('file',file);const d=await apiUpload('/api/profile/character-upload',form);renderProfile(d.profile);toast(d.message||'کاراکتر ثبت شد.');input.value=''}catch(e){toast(e.message)}}
async function removeMyCharacter(){if(!confirm('کاراکتر شخصی از پروفایل برداشته شود؟'))return;try{const d=await api('/api/profile/character-upload','DELETE');renderProfile(d.profile);toast(d.message||'کاراکتر برداشته شد.')}catch(e){toast(e.message)}}
async function loadProfileExtras(){try{const [a,h,i]=await Promise.all([api('/api/achievements'),api('/api/profile/history'),api('/api/shop/inventory')]);renderInventory(i.items);document.getElementById('achievementList').innerHTML=a.achievements.map(x=>`<div class="list-card ${x.unlocked?'unlocked':'locked'}"><div><b>${x.icon} ${escapeHtml(x.title)}</b><small>${escapeHtml(x.description)}</small></div><span>${x.unlocked?'✅':'🔒'}</span></div>`).join('');document.getElementById('matchHistory').innerHTML=h.history.map(x=>`<div class="list-card"><div><b>${gameLabel(x.game)} · ${x.won?'برد':'باخت'}</b><small>${new Date(x.created_at).toLocaleString('fa-IR')}</small></div><div class="history-rewards"><b>+${fmt(x.xp)} XP</b></div></div>`).join('')||'<p class="helper">مسابقه‌ای ثبت نشده.</p>'}catch(e){toast(e.message)}}
function gameLabel(g){return ({math:'نبرد ریاضی',iq:'نبرد هوش',ttt:'دوز',penalty:'پنالتی',basketball:'بسکتبال',volleyball:'والیبال',guess:'حدس عدد',memory:'حافظه', 'neon-runner':'NEON RUNNER (قدیمی)','neon-breakout':'NEON BREAKOUT','space-shooter':'SPACE SHOOTER','neon-drift':'NEON DRIFT','coin-dash':'Coin Dash'})[g]||g}
function shareInvite(){if(!referralLink){toast('لینک دعوت هنوز آماده نیست.');return}const url='https://t.me/share/url?url='+encodeURIComponent(referralLink)+'&text='+encodeURIComponent('بیا تو GAME ARENA با هم بازی کنیم! 🎮');if(tg?.openTelegramLink)tg.openTelegramLink(url);else window.open(url,'_blank')}

// Admin workspace
async function loadAdmin(){try{const [s,p,g,l,t,diff,fj,tx,se,ev,audit,reports,seasons]=await Promise.all([api('/api/admin/stats'),api('/api/admin/products'),api('/api/admin/games'),api('/api/admin/leagues'),api('/api/admin/tournaments'),api('/api/admin/ttt-difficulty'),api('/api/admin/force-join'),api('/api/admin/transactions?limit=30'),api('/api/admin/security/events'),api('/api/admin/events'),api('/api/admin/audit'),api('/api/admin/reports'),api('/api/admin/seasons')]);document.getElementById('adminStats').innerHTML=`<div><b>${fmt(s.users)}</b><small>کاربر</small></div><div><b>${fmt(s.games)}</b><small>بازی</small></div><div><b>${fmt(s.coins)}</b><small>سکه در گردش</small></div><div><b>${fmt(s.daily_active)}</b><small>ورود امروز</small></div><div><b>${fmt(s.banned)}</b><small>مسدود</small></div><div><b>${fmt(s.xp)}</b><small>XP کل</small></div>`;renderAdminProducts(p.products);renderAdminGames(g.games);renderAdminTournaments(t.tournaments);renderAdminTransactions(tx.transactions);renderSecurityEvents(se);renderAdminEvents(ev.events);renderAdminAudit(audit.items);renderAdminReports(reports.reports);renderAdminSeasons(seasons.seasons);document.getElementById('leagueJson').value=JSON.stringify(l.leagues,null,2);document.getElementById('tttDifficulty').value=diff.difficulty;document.getElementById('forceJoinEnabled').checked=fj.enabled;document.getElementById('forceJoinChat').value=fj.chat_id||'';document.getElementById('forceJoinUrl').value=fj.invite_url||'';document.getElementById('forceJoinTitle').value=fj.title||''}catch(e){toast(e.message)}}
function renderAdminReports(items){const el=document.getElementById('adminReports');if(!el)return;el.innerHTML=(items||[]).map(x=>`<div class="list-card"><div><b>#${x.id} · ${escapeHtml(x.reason)} · گزارش‌شده: ${fmt(x.target_id)}</b><small>گزارش‌دهنده ${fmt(x.reporter_id)} · ${escapeHtml(x.details||'بدون توضیح')} · ${new Date(x.created_at).toLocaleString('fa-IR')} · ${escapeHtml(x.status)}</small></div>${x.status==='open'?`<button onclick="adminReviewReport(${x.id})">تأیید بررسی</button>`:''}</div>`).join('')||'<p class="helper">گزارش بازیکنی ثبت نشده است.</p>'}
function renderAdminSeasons(items){const el=document.getElementById('adminSeasons');if(!el)return;el.innerHTML=(items||[]).map(x=>`<div class="list-card"><div><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.status)} · پایان ${new Date(x.ends_at).toLocaleString('fa-IR')}</small></div></div>`).join('')||'<p class="helper">هنوز فصلی ثبت نشده است.</p>'}
async function adminReviewReport(id){try{await api(`/api/admin/reports/${id}/review`,'POST',{});toast('گزارش بررسی شد.');loadAdmin()}catch(e){toast(e.message)}}
async function adminCreateSeason(){const name=document.getElementById('seasonAdminName').value.trim(),duration_days=Number(document.getElementById('seasonAdminDays').value||30);if(name.length<3||!Number.isInteger(duration_days)||duration_days<7||duration_days>120){toast('نام و مدت فصل معتبر وارد کن.');return}if(!confirm('فصل فعال قبلی بسته و فصل جدید آغاز می‌شود. ادامه می‌دهی؟'))return;try{await api('/api/admin/seasons','POST',{name,duration_days});toast('فصل جدید شروع شد.');document.getElementById('seasonAdminName').value='';loadAdmin();loadSeasonHub()}catch(e){toast(e.message)}}
function renderAdminProducts(items){document.getElementById('adminProducts').innerHTML=items.map(p=>`<div class="list-card"><div><b>${escapeHtml(p.name)}</b><small>#${p.id} · ${categoryLabel(p.category)} · ${fmt(p.price_coins)} سکه · ${p.reward_only?'جایزه مالک':'فروشگاهی'} · ${p.active?'فعال':'غیرفعال'}</small></div><div class="list-actions"><button onclick="document.getElementById('grantProductId').value='${p.id}'">انتخاب برای اعطا</button><button onclick="adminEditProduct(${p.id})">ویرایش قیمت</button><button class="small-danger" onclick="adminDeleteProduct(${p.id})">حذف</button></div></div>`).join('')||'<p class="helper">محصولی ثبت نشده است.</p>'}
function renderAdminTransactions(items){const el=document.getElementById('adminTransactions');if(!el)return;const actions={purchase:'خرید کاربر',owner_grant:'اعطای جایزه مالک',pack_open:'بازکردن بسته',pack_reward:'دریافت محتوای بسته'};el.innerHTML=items.map(x=>`<div class="list-card"><div><b>${escapeHtml(x.name||'کاربر')} · ID ${x.user_id} ${x.username?'@'+escapeHtml(x.username):''}</b><small>${x.kind==='wallet'?`${escapeHtml(x.reason)} · موجودی بعد از تراکنش: ${fmt(x.balance_after)}`:`${actions[x.action]||escapeHtml(x.action)} · ${escapeHtml(x.product_name||'آیتم')} × ${fmt(x.quantity)} · ${escapeHtml(x.details||'')}`} · ${new Date(x.created_at).toLocaleString('fa-IR')}</small></div>${x.kind==='wallet'?`<strong class="${x.amount>=0?'positive':'negative'}">${x.amount>0?'+':''}${fmt(x.amount)} 🪙</strong>`:`<strong class="status-tag">آیتمی</strong>`}</div>`).join('')||'<p class="helper">تراکنشی ثبت نشده است.</p>'}
async function loadAdminTransactions(){const q=document.getElementById('transactionUserId').value.trim();try{const d=await api('/api/admin/transactions?limit=100'+(q?'&user_id='+encodeURIComponent(q):''));renderAdminTransactions(d.transactions)}catch(e){toast(e.message)}}
function renderSecurityEvents(data){document.getElementById('securityEventSummary').textContent=`${fmt(data.open_count)} گزارش نیازمند بررسی · آخرین ${fmt(data.events.length)} رویداد`;document.getElementById('securityEvents').innerHTML=data.events.map(x=>`<div class="list-card security-event ${x.severity==='high'?'high-risk':''}"><div><b>${x.severity==='high'?'🚨':'⚠️'} ${escapeHtml(x.code)} · کاربر ${x.user_id}</b><small>${escapeHtml(x.detail)} · ${new Date(x.created_at).toLocaleString('fa-IR')} · ${x.reviewed?'بررسی‌شده':'در انتظار بررسی'}</small></div>${x.reviewed?'':`<button onclick="adminReviewSecurity(${x.id})">علامت بررسی</button>`}</div>`).join('')||'<p class="helper">رفتار مشکوکی ثبت نشده است.</p>'}
async function loadSecurityEvents(){try{renderSecurityEvents(await api('/api/admin/security/events'))}catch(e){toast(e.message)}}
async function adminReviewSecurity(id){try{await api(`/api/admin/security/events/${id}/review`,'POST',{});loadSecurityEvents()}catch(e){toast(e.message)}}
function renderAdminTournaments(items){document.getElementById('adminTournaments').innerHTML=items.map(t=>{let bracket='';if(t.bracket){bracket=t.bracket.map((round,ri)=>`<div class="bracket-round"><b>دور ${fmt(ri+1)}</b>${round.map((m,mi)=>`<div class="bracket-match"><span>${m.p1} ${m.p2?'vs '+m.p2:'(استراحت)'}</span>${m.winner?`<em>برنده: ${m.winner}</em>`:`<div><button onclick="adminSetTournamentWinner(${t.id},${ri},${mi},${m.p1})">${m.p1}</button>${m.p2?`<button onclick="adminSetTournamentWinner(${t.id},${ri},${mi},${m.p2})">${m.p2}</button>`:''}</div>`}</div>`).join('')}</div>`).join('')}return `<div class="list-card admin-tournament"><div><b>#${t.id} · ${escapeHtml(t.name)}</b><small>${escapeHtml(t.status)} · ${fmt(t.players.length)} شرکت‌کننده · ${fmt(t.prize_coins)} سکه</small></div>${t.status==='open'?`<button onclick="adminStartTournament(${t.id})">ساخت جدول حذفی</button>`:t.status==='completed'?'<span class="status-tag">پایان‌یافته</span>':''}</div>${bracket}`}).join('')||'<p class="helper">تورنمنتی ساخته نشده است.</p>'}
async function adminStartTournament(id){try{await api(`/api/admin/tournaments/${id}/start`,'POST',{});toast('جدول حذفی ساخته شد.');loadAdmin()}catch(e){toast(e.message)}}
async function adminSetTournamentWinner(id,round_index,match_index,winner_id){if(!confirm(`کاربر ${winner_id} برنده این مسابقه ثبت شود؟`))return;try{await api(`/api/admin/tournaments/${id}/match-result`,'POST',{round_index,match_index,winner_id});toast('نتیجه مسابقه ثبت شد.');loadAdmin()}catch(e){toast(e.message)}}
function renderAdminGames(items){document.getElementById('adminGameToggles').innerHTML=items.map(x=>`<label class="toggle-row"><span>${escapeHtml(gameLabel(x.id))}</span><input type="checkbox" ${x.enabled?'checked':''} onchange="adminToggleGame('${x.id}',this.checked)"></label>`).join('')}
function parseBundleItems(raw){if(!raw.trim())return[];return raw.split(',').map(part=>{const [id,quantity='1']=part.trim().split(':');return {product_id:Number(id),quantity:Number(quantity)}}).filter(x=>Number.isInteger(x.product_id)&&x.product_id>0&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=100)}
async function adminCreateProduct(){const name=document.getElementById('productName').value.trim(),description=document.getElementById('productDesc').value.trim(),category=document.getElementById('productCategory').value,rarity=document.getElementById('productRarity').value,price_coins=Number(document.getElementById('productPrice').value||0),reward_only=document.getElementById('productRewardOnly').checked||['pack','gift','item'].includes(category),bundle_items=parseBundleItems(document.getElementById('productBundleItems').value);if(!name||!Number.isInteger(price_coins)||price_coins<0){toast('نام و قیمت معتبر وارد کن.');return}if(category==='pack'&&!bundle_items.length){toast('برای بسته حداقل یک محتوا با قالب شناسه:تعداد وارد کن.');return}try{let image_url=null;const file=document.getElementById('productImage').files[0];if(file){const form=new FormData();form.append('file',file);image_url=(await apiUpload('/api/admin/products/upload',form)).image_url}await api('/api/admin/products','POST',{name,description,category,rarity,price_coins,image_url,reward_only,bundle_items,active:true});toast('محصول / بسته ثبت شد.');['productName','productDesc','productPrice','productImage','productBundleItems'].forEach(id=>document.getElementById(id).value='');document.getElementById('productRewardOnly').checked=false;loadAdmin()}catch(e){toast(e.message)}}
async function adminEditProduct(id){try{const list=(await api('/api/admin/products')).products,p=list.find(x=>x.id===id);if(!p)return;const price=prompt('قیمت جدید به سکه:',String(p.price_coins));if(price===null)return;const n=Number(price);if(!Number.isInteger(n)||n<0){toast('قیمت معتبر نیست.');return}await api(`/api/admin/products/${id}`,'PUT',{name:p.name,description:p.description,category:p.category,rarity:p.rarity,price_coins:n,image_url:p.image_url,reward_only:p.reward_only,bundle_items:p.bundle_items||[],active:p.active});toast('محصول به‌روزرسانی شد.');loadAdmin()}catch(e){toast(e.message)}}
async function adminDeleteProduct(id){if(!confirm('این محصول از فروشگاه غیرفعال شود؟'))return;try{await api(`/api/admin/products/${id}`,'DELETE');toast('محصول غیرفعال شد.');loadAdmin()}catch(e){toast(e.message)}}
async function adminGrantReward(){const user_id=Number(document.getElementById('grantUserId').value),product_id=Number(document.getElementById('grantProductId').value),quantity=Number(document.getElementById('grantQuantity').value||1);if(!user_id||!product_id||!Number.isInteger(quantity)||quantity<1||quantity>100){toast('شناسه کاربر، شناسه محصول و تعداد معتبر وارد کن.');return}if(!confirm(`جایزه محصول #${product_id} به تعداد ${quantity} برای کاربر ${user_id} اعطا شود؟`))return;try{const d=await api('/api/admin/rewards/grant','POST',{user_id,product_id,quantity});toast(`${d.product} به کاربر اعطا شد.`);document.getElementById('grantProductId').value='';}catch(e){toast(e.message)}}
async function adminAdjustCoins(){const user_id=Number(document.getElementById('adjustUserId').value),amount=Number(document.getElementById('adjustAmount').value),reason=document.getElementById('adjustReason').value.trim()||'تغییر موجودی توسط مدیر';if(!user_id||!Number.isInteger(amount)||amount===0){toast('شناسه و مقدار معتبر وارد کن.');return}try{const d=await api('/api/admin/coins','POST',{user_id,amount,reason});toast('موجودی جدید: '+fmt(d.coins)+' سکه');document.getElementById('adjustAmount').value='';loadAdmin()}catch(e){toast(e.message)}}
async function adminBan(banned){const user_id=Number(document.getElementById('banUserId').value);if(!user_id){toast('شناسه کاربر را وارد کن.');return}try{await api('/api/admin/ban','POST',{user_id,banned});toast(banned?'کاربر مسدود شد.':'مسدودی کاربر برداشته شد.');adminSearchUsers()}catch(e){toast(e.message)}}
async function adminBroadcast(){const message=document.getElementById('broadcastText').value.trim();if(!message){toast('متن پیام را وارد کن.');return}if(!confirm('پیام برای همه کاربران فعال ارسال شود؟'))return;try{const d=await api('/api/admin/broadcast','POST',{message});toast(`ارسال شد: ${d.sent} · ناموفق: ${d.failed}`);document.getElementById('broadcastText').value=''}catch(e){toast(e.message)}}
async function adminCreateTournament(){const name=document.getElementById('tournamentName').value.trim(),prize_coins=Number(document.getElementById('tournamentPrize').value||0),max_players=Number(document.getElementById('tournamentCapacity').value||16),game=document.getElementById('tournamentGame').value;if(!name){toast('نام تورنمنت را وارد کن.');return}try{await api('/api/admin/tournaments','POST',{name,game,prize_coins,max_players});toast('تورنمنت ساخته شد.');document.getElementById('tournamentName').value='';loadCompetition()}catch(e){toast(e.message)}}
async function adminSaveTTTDifficulty(){const difficulty=document.getElementById('tttDifficulty').value;try{await api('/api/admin/ttt-difficulty','PUT',{difficulty});toast('درجه سختی دوز ذخیره شد.')}catch(e){toast(e.message)}}
function renderAdminEvents(items){const el=document.getElementById('adminEvents');if(!el)return;el.innerHTML=(items||[]).map(e=>`<div class="list-card"><div><b>#${e.id} · ${escapeHtml(e.title)}</b><small>+${fmt(e.bonus_xp)} XP · تا ${new Date(e.ends_at).toLocaleString('fa-IR')} · ${e.active?'فعال':'غیرفعال'}</small></div><button onclick="adminToggleEvent(${e.id})">${e.active?'غیرفعال‌کردن':'فعال‌کردن'}</button></div>`).join('')||'<p class="helper">رویدادی ثبت نشده است.</p>'}
function renderAdminAudit(items){const el=document.getElementById('adminAudit');if(!el)return;el.innerHTML=(items||[]).map(x=>`<div class="list-card"><div><b>${escapeHtml(x.action)} · هدف ${x.target_id??'—'}</b><small>${escapeHtml(x.detail)} · ${new Date(x.created_at).toLocaleString('fa-IR')}</small></div></div>`).join('')||'<p class="helper">گزارش مدیریتی جدیدی ثبت نشده است.</p>'}
async function adminSetVip(){const user_id=Number(document.getElementById('vipUserId').value),tier=document.getElementById('vipTier').value;if(!user_id){toast('شناسه کاربر را وارد کن.');return}try{await api('/api/admin/vip','POST',{user_id,tier});toast('سطح VIP ذخیره شد.');loadAdmin()}catch(e){toast(e.message)}}
async function adminCreateEvent(){const title=document.getElementById('eventTitle').value.trim(),description=document.getElementById('eventDescription').value.trim(),bonus_xp=Number(document.getElementById('eventBonusXp').value||0),duration_hours=Number(document.getElementById('eventDuration').value||72);if(!title){toast('عنوان رویداد را وارد کن.');return}try{await api('/api/admin/events','POST',{title,description,bonus_xp,duration_hours,active:true});toast('رویداد ساخته شد.');document.getElementById('eventTitle').value='';document.getElementById('eventDescription').value='';loadAdmin();const d=await api('/api/events');renderEvents(d.events)}catch(e){toast(e.message)}}
async function adminToggleEvent(id){try{await api(`/api/admin/events/${id}/toggle`,'PUT',{});loadAdmin()}catch(e){toast(e.message)}}
async function adminToggleGame(game,enabled){try{await api('/api/admin/games','PUT',{game,enabled});toast('تنظیم بازی ذخیره شد.')}catch(e){toast(e.message)}}
async function forceJoinForm(){return {enabled:document.getElementById('forceJoinEnabled').checked,chat_id:document.getElementById('forceJoinChat').value.trim(),invite_url:document.getElementById('forceJoinUrl').value.trim(),title:document.getElementById('forceJoinTitle').value.trim()}}
async function adminTestForceJoin(){try{const d=await api('/api/admin/force-join/test','POST',await forceJoinForm());toast('✅ دسترسی ربات در '+d.channel_title+' تأیید شد.')}catch(e){toast(e.message)}}
async function adminSaveForceJoin(){try{const d=await api('/api/admin/force-join','PUT',await forceJoinForm());toast(d.enabled?'جویین اجباری فعال شد.':'جویین اجباری غیرفعال شد.')}catch(e){toast(e.message)}}
async function adminSaveLeagues(){try{const leagues=JSON.parse(document.getElementById('leagueJson').value);await api('/api/admin/leagues','PUT',{leagues});toast('لیگ‌ها به‌روزرسانی شدند.')}catch(e){toast(e.message||'ساختار JSON معتبر نیست.')}}
async function adminSetVerified(user_id,verified){try{await api('/api/admin/verify','POST',{user_id,verified});toast(verified?'تیک آبی فعال شد.':'تیک آبی برداشته شد.');adminSearchUsers()}catch(e){toast(e.message)}}
async function adminSearchUsers(){const q=document.getElementById('adminUserQuery').value.trim();try{const d=await api('/api/admin/users?q='+encodeURIComponent(q));document.getElementById('adminUsers').innerHTML=d.users.map(u=>`<div class="list-card"><div><b>${escapeHtml(u.name)} ${u.username?'@'+escapeHtml(u.username):''}</b><small>ID: ${u.id} · ${fmt(u.coins)} سکه · ${u.banned?'مسدود':'فعال'} · ${u.is_owner?'مالک':u.verified?'تأییدشده':'بدون تیک'} · VIP: ${escapeHtml(u.vip_tier||'none')}</small></div><div class="list-actions"><button onclick="document.getElementById('adjustUserId').value='${u.id}';document.getElementById('banUserId').value='${u.id}';document.getElementById('verifyUserId').value='${u.id}';document.getElementById('grantUserId').value='${u.id}';document.getElementById('transactionUserId').value='${u.id}';document.getElementById('vipUserId').value='${u.id}'">انتخاب</button>${u.is_owner?'':`<button onclick="adminSetVerified(${u.id},${!u.verified})">${u.verified?'حذف تیک':'تیک آبی'}</button>`}</div></div>`).join('')||'<p class="helper">کاربری پیدا نشد.</p>'}catch(e){toast(e.message)}}

document.addEventListener('keydown',e=>{if(document.getElementById('modal')?.classList.contains('hidden'))return;if(e.key==='Enter'&&document.activeElement?.id==='mathAnswer')submitMath();if(e.key==='Enter'&&document.activeElement?.id==='guessInput')submitGuess()});
boot();
